def _iw2(rid, exp, vol, nrows, nholes, params, missing, spec, extra_remark="", paper=None):
    nparams = len(params.split("|"))
    rec(rid,
        fmt=f"ZIP of {nholes} per-hole CSV composite tables ({exp}-<hole>-IWREPORT.csv) + IWREPORT-README.txt + site-location HTML",
        npts=f"No spectra; {nrows} IW sample rows x {nparams} parameter columns",
        missing=missing,
        prep="Yes (shipboard-reduced concentrations)",
        prep_methods="(standard JRSO shipboard procedure, not described in dataset) 1) Pore water squeezed from whole-round core samples (or Rhizon), filtered; 2) splits analysed by titration (alkalinity, pH, chloride), refractometer (salinity), ion chromatography (major ions), ICP-AES (minor/major elements" + (", colorimetric UV-Vis (NH4+, PO4 3-)" if spec else "") + "); 3) calibration against IAPSO seawater/standards; 4) results merged per sample into composite report",
        target="Pore-water (interstitial water) chemistry vs depth: " + params.replace(" | ", ", "),
        mode="Shipboard wet-chemistry analyses of squeezed pore water (no spectral acquisition in dataset)",
        wl=NA + " (ICP-AES emission lines listed per column" + ("; NH4+ 640 nm, PO4 885 nm colorimetry" if spec else "") + ")",
        res=NA,
        make="JOIDES Resolution shipboard lab (ICP-AES, ion chromatograph, autotitrator, refractometer" + (", Agilent Cary UV-Vis spectrophotometer" if spec else "") + "); models not stated in dataset",
        path=NA,
        ts="No (depth series: one row per IW sample down-hole)",
        chemo="No",
        refs=_IODP_REF[vol],
        remarks=f"Paper PDF is the {_IODP_PAPER[paper or vol]} (no IW methods text); 'bdl' = below detection limit" + extra_remark,
        cond="Shipboard laboratory, ambient conditions; samples from cored sediment/rock",
        absorb=NA,
        refm="IAPSO standard seawater / in-house standards (standard shipboard QA/QC; not in dataset)",
        gold=NA, peaks=NA,
        struct="Inorganic ions: Na+, K+, Ca2+, Mg2+, Cl-, Br-, SO4 2-, NH4+ [NH4+], PO4 3- (as applicable)")


