def _rsc2(rid, exp, vol, nspectra, nfiles, nsections, nreduced, bands, lo, hi, sensor, missing, extra_remark="", extra_zips=True):
    rec(rid,
        fmt="ZIP(s): data_by_hole per-hole CSV (L*, a*, b*, XYZ, file names, timestamps)" + (" + CCSF scaled / compiled-scale / splice variants" if extra_zips else "") + " + supplementary_material raw_data_files per section (norm_*_rsc.csv % reflectance, raw_*_rsc.csv counts, *.RSC headers), configuration_files, standards_measured; RSC-README.txt",
        npts=f"{nspectra:,} reflectance spectra x {bands} bands ({lo}-{hi} nm, 2 nm) = {nspectra*bands:,} values in {nfiles:,} normalised files ({nsections:,} section halves); {nreduced:,} reduced colour rows",
        missing=missing,
        prep="Yes (white/dark normalisation in norm files; raw counts also given)",
        prep_methods="1) Dark and white reference correction -> % reflectance; 2) spectra binned to 2 nm; 3) CIE XYZ tristimulus and L*a*b*, chroma, hue computed (D50/10 deg in QE Pro headers); 4) QA/QC colour standard measured",
        target="Sediment/rock colour (lightness L*, a*, b*) down-core for lithostratigraphy and correlation",
        mode="Diffuse reflectance with integrating sphere (d/8 geometry) in contact with split-core surface covered by clear film, Section Half Multisensor Logger (SHMSL)",
        wl=f"{lo}-{hi} (2 nm bins; README states 380-700)",
        res="Not reported (2 nm binning)",
        make=f"{sensor} spectrometer + integrating sphere on SHMSL (README lists OOUSB4000V)",
        path=NA,
        ts="No (depth series; typically 2-5 cm spacing)",
        chemo="No",
        refs=_IODP_REF[vol],
        remarks=f"Paper PDF is the {_IODP_PAPER[vol]}" + extra_remark,
        cond="Shipboard core laboratory; split section halves at room temperature, measured shortly after splitting",
        absorb=NA,
        refm="White and dark calibration references; QAQC colour standard",
        gold=NA,
        peaks="Broad VIS slopes: Fe-oxide absorption (<550 nm, raises a*/b*), organic matter/sulfides darken (low L*), carbonate/biosiliceous ooze bright (high L*)",
        struct=NA)


